-- ============================================================
insert into vocabulary (id, word, ipa, part_of_speech, translation_pt, example_en, example_pt, cefr_level, tags) values
('30000000-0000-0000-0000-000000002191', 'a double-edged sword', '/ə ˈdʌbəl edʒd sɔːrd/', 'phrase', 'uma faca de dois gumes', 'Social media can be a double-edged sword for small businesses.', 'As redes sociais podem ser uma faca de dois gumes para pequenas empresas.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002192', 'the tip of the iceberg', '/ðə tɪp əv ði ˈaɪsbɜːrɡ/', 'phrase', 'a ponta do iceberg', 'These complaints are just the tip of the iceberg.', 'Essas reclamações são só a ponta do iceberg.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002193', 'read between the lines', '/riːd bɪˈtwiːn ðə laɪnz/', 'phrase', 'ler nas entrelinhas', 'You have to read between the lines to understand what she really meant.', 'Você precisa ler nas entrelinhas para entender o que ela realmente quis dizer.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002194', 'food for thought', '/fuːd fɔːr θɔːt/', 'phrase', 'algo para refletir', 'The report gave the board plenty of food for thought.', 'O relatório deu à diretoria bastante o que pensar.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002195', 'a grey area', '/ə ɡreɪ ˈeriə/', 'phrase', 'uma zona cinzenta', 'The new regulation leaves a lot of room in a grey area.', 'A nova regulamentação deixa muito espaço em uma zona cinzenta.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002196', 'a blessing in disguise', '/ə ˈblesɪŋ ɪn dɪsˈɡaɪz/', 'phrase', 'uma bênção disfarçada', 'Losing that client turned out to be a blessing in disguise.', 'Perder aquele cliente acabou sendo uma bênção disfarçada.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002197', 'to weather the storm', '/tuː ˈweðər ðə stɔːrm/', 'phrase', 'enfrentar a tempestade', 'The company managed to weather the storm during the crisis.', 'A empresa conseguiu enfrentar a tempestade durante a crise.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002198', 'to be at a crossroads', '/tuː biː æt ə ˈkrɔːsroʊdz/', 'phrase', 'estar numa encruzilhada', 'The organization is at a crossroads and must choose a new direction.', 'A organização está numa encruzilhada e precisa escolher um novo rumo.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002199', 'to hit home', '/tuː hɪt hoʊm/', 'phrase', 'atingir em cheio', 'Her comment about the delays really hit home.', 'O comentário dela sobre os atrasos atingiu em cheio.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002200', 'to shed light on', '/tuː ʃed laɪt ɒn/', 'phrase', 'esclarecer, lançar luz sobre', 'The investigation shed light on the causes of the failure.', 'A investigação esclareceu as causas da falha.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002201', 'to draw the line', '/tuː drɔː ðə laɪn/', 'phrase', 'estabelecer um limite', 'We need to draw the line between feedback and criticism.', 'Precisamos estabelecer um limite entre feedback e crítica.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002202', 'to bridge the gap', '/tuː brɪdʒ ðə ɡæp/', 'phrase', 'reduzir a distância', 'The new program aims to bridge the gap between theory and practice.', 'O novo programa visa reduzir a distância entre teoria e prática.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002203', 'an uphill battle', '/æn ˈʌphɪl ˈbætl/', 'phrase', 'uma batalha difícil', 'Convincing investors was an uphill battle.', 'Convencer os investidores foi uma batalha difícil.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002204', 'to set the tone', '/tuː set ðə toʊn/', 'phrase', 'dar o tom', 'The opening speech set the tone for the entire conference.', 'O discurso de abertura deu o tom para toda a conferência.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002205', 'to strike a balance', '/tuː straɪk ə ˈbæləns/', 'phrase', 'encontrar um equilíbrio', 'It is hard to strike a balance between speed and quality.', 'É difícil encontrar um equilíbrio entre velocidade e qualidade.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002206', 'to turn a blind eye', '/tuː tɜːrn ə blaɪnd aɪ/', 'phrase', 'fazer vista grossa', 'Management chose to turn a blind eye to the problem.', 'A gerência escolheu fazer vista grossa para o problema.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002207', 'to be in the same boat', '/tuː biː ɪn ðə seɪm boʊt/', 'phrase', 'estar no mesmo barco', 'Every department is in the same boat when it comes to budget cuts.', 'Todo departamento está no mesmo barco quando se trata de cortes no orçamento.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002208', 'to move the goalposts', '/tuː muːv ðə ˈɡoʊlpoʊsts/', 'phrase', 'mudar as regras no meio do jogo', 'It felt unfair when the client moved the goalposts halfway through the project.', 'Pareceu injusto quando o cliente mudou as regras no meio do projeto.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002209', 'to scratch the surface', '/tuː skrætʃ ðə ˈsɜːrfɪs/', 'phrase', 'arranhar a superfície', 'This report only scratches the surface of the problem.', 'Esse relatório apenas arranha a superfície do problema.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002210', 'a ripple effect', '/ə ˈrɪpəl ɪˈfekt/', 'phrase', 'um efeito cascata', 'The price increase had a ripple effect across the whole industry.', 'O aumento de preço teve um efeito cascata em toda a indústria.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002211', 'to open a can of worms', '/tuː ˈoʊpən ə kæn əv wɜːrmz/', 'phrase', 'abrir uma caixa de pandora', 'Asking about the budget opened a can of worms in the meeting.', 'Perguntar sobre o orçamento abriu uma caixa de pandora na reunião.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002212', 'to read the room', '/tuː riːd ðə ruːm/', 'phrase', 'perceber o clima', 'A good speaker knows how to read the room.', 'Um bom palestrante sabe como perceber o clima.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002213', 'to rock the boat', '/tuː rɒk ðə boʊt/', 'phrase', 'balançar o barco, causar confusão', 'Nobody wanted to rock the boat right before the deal closed.', 'Ninguém queria balançar o barco bem antes de o acordo ser fechado.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002214', 'to keep something at bay', '/tuː kiːp ˈsʌmθɪŋ æt beɪ/', 'phrase', 'manter algo sob controle', 'Regular audits help keep fraud at bay.', 'Auditorias regulares ajudam a manter a fraude sob controle.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002215', 'to take something with a grain of salt', '/tuː teɪk ˈsʌmθɪŋ wɪð ə ɡreɪn əv sɔːlt/', 'phrase', 'levar algo com ressalvas', 'You should take that rumor with a grain of salt.', 'Você deveria levar esse boato com ressalvas.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002216', 'to be a game changer', '/tuː biː ə ɡeɪm ˈtʃeɪndʒər/', 'phrase', 'ser um divisor de águas', 'The new technology was a game changer for the industry.', 'A nova tecnologia foi um divisor de águas para a indústria.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002217', 'to leave no stone unturned', '/tuː liːv noʊ stoʊn ʌnˈtɜːrnd/', 'phrase', 'revirar tudo, não deixar pedra sobre pedra', 'The team left no stone unturned in their search for a solution.', 'A equipe revirou tudo em busca de uma solução.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002218', 'to go the extra mile', '/tuː ɡoʊ ði ˈekstrə maɪl/', 'phrase', 'fazer um esforço extra', 'She always goes the extra mile for her clients.', 'Ela sempre faz um esforço extra pelos clientes dela.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002219', 'to be the elephant in the room', '/tuː biː ði ˈeləfənt ɪn ðə ruːm/', 'phrase', 'ser o elefante na sala', 'The budget cuts were the elephant in the room during the meeting.', 'Os cortes no orçamento eram o elefante na sala durante a reunião.', 'C1', array['idioms']),
('30000000-0000-0000-0000-000000002220', 'to come full circle', '/tuː kʌm fʊl ˈsɜːrkəl/', 'phrase', 'fechar o ciclo', 'After years abroad, her career came full circle when she returned to her first company.', 'Depois de anos no exterior, a carreira dela fechou o ciclo quando voltou para a primeira empresa.', 'C1', array['idioms']);

