-- Lição 366: Metáforas de clareza e ambiguidade (a double-edged sword, the tip of the iceberg, read between the lines, food for thought, a grey area, a blessing in disguise)
insert into exercises (lesson_id, type, sort_order, content) values
('20000000-0000-0000-0000-000000000366', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002191", "show_image": false}'),
('20000000-0000-0000-0000-000000000366', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002193", "show_image": false}'),
('20000000-0000-0000-0000-000000000366', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002196", "show_image": false}'),
('20000000-0000-0000-0000-000000000366', 'multiple_choice', 4, '{"question": "Social media can be ___ for small businesses.", "audio_text": null, "options": ["a double-edged sword", "food for thought", "a grey area"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000366', 'multiple_choice', 5, '{"question": "These complaints are just ___.", "audio_text": null, "options": ["the tip of the iceberg", "a blessing in disguise", "a grey area"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000366', 'matching', 6, '{"pairs": [{"left": "a double-edged sword", "right": "uma faca de dois gumes"}, {"left": "the tip of the iceberg", "right": "a ponta do iceberg"}, {"left": "read between the lines", "right": "ler nas entrelinhas"}, {"left": "food for thought", "right": "algo para refletir"}, {"left": "a grey area", "right": "uma zona cinzenta"}, {"left": "a blessing in disguise", "right": "uma bênção disfarçada"}]}'),
('20000000-0000-0000-0000-000000000366', 'fill_blank', 7, '{"sentence": "The report gave the board plenty of ___.", "options": ["food for thought", "a grey area", "read between the lines"], "correct": "food for thought", "translation": "O relatório deu à diretoria bastante o que pensar."}'),
('20000000-0000-0000-0000-000000000366', 'fill_blank', 8, '{"sentence": "Losing that client turned out to be ___.", "options": ["a blessing in disguise", "a double-edged sword", "the tip of the iceberg"], "correct": "a blessing in disguise", "translation": "Perder aquele cliente acabou sendo uma bênção disfarçada."}'),
('20000000-0000-0000-0000-000000000366', 'word_order', 9, '{"words": ["You", "have", "to", "read", "between", "the", "lines", "to", "understand", "what", "she", "really", "meant"], "correct_sentence": "You have to read between the lines to understand what she really meant", "translation": "Você precisa ler nas entrelinhas para entender o que ela realmente quis dizer"}'),
('20000000-0000-0000-0000-000000000366', 'word_order', 10, '{"words": ["The", "new", "regulation", "leaves", "a", "lot", "of", "room", "in", "a", "grey", "area"], "correct_sentence": "The new regulation leaves a lot of room in a grey area", "translation": "A nova regulamentação deixa muito espaço em uma zona cinzenta"}'),
('20000000-0000-0000-0000-000000000366', 'reading', 11, '{"passage": "Figurative language allows speakers to describe complexity in a single image. A ''double-edged sword'' has both benefits and risks, while ''the tip of the iceberg'' suggests a much bigger hidden problem. When people ''read between the lines'', they understand a hidden meaning, and something described as ''a grey area'' is neither clearly right nor wrong.", "translation": "A linguagem figurada permite que falantes descrevam complexidade em uma única imagem. Uma ''double-edged sword'' tem tanto benefícios quanto riscos, enquanto ''the tip of the iceberg'' sugere um problema oculto muito maior. Quando as pessoas ''read between the lines'', elas entendem um significado oculto, e algo descrito como ''a grey area'' não é claramente certo nem errado.", "question": "What does ''the tip of the iceberg'' suggest, according to the text?", "options": ["A much bigger hidden problem", "A clear and simple issue", "A positive outcome"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000366', 'listening', 12, '{"audio_text": "Social media can be a double-edged sword for small businesses. These complaints are just the tip of the iceberg. The new regulation leaves a lot of room in a grey area.", "question": "What can social media be for small businesses, according to the audio?", "options": ["A double-edged sword", "A blessing in disguise", "Food for thought"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000366', 'dictation', 13, '{"audio_text": "These complaints are just the tip of the iceberg.", "expected": "These complaints are just the tip of the iceberg."}'),
('20000000-0000-0000-0000-000000000366', 'typing', 14, '{"prompt_pt": "Traduza: ''É preciso ler nas entrelinhas; essas reclamações são só a ponta do iceberg.''", "expected": "You have to read between the lines; these complaints are just the tip of the iceberg.", "ai_review": true}'),

-- Lição 367: Idioms de desafio e mudança (to weather the storm, to be at a crossroads, to hit home, to shed light on, to draw the line, to bridge the gap)
('20000000-0000-0000-0000-000000000367', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002197", "show_image": false}'),
('20000000-0000-0000-0000-000000000367', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002198", "show_image": false}'),
('20000000-0000-0000-0000-000000000367', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002202", "show_image": false}'),
('20000000-0000-0000-0000-000000000367', 'multiple_choice', 4, '{"question": "The company managed to ___ during the crisis.", "audio_text": null, "options": ["weather the storm", "hit home", "draw the line"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000367', 'multiple_choice', 5, '{"question": "The organization is ___ and must choose a new direction.", "audio_text": null, "options": ["at a crossroads", "the tip of the iceberg", "a grey area"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000367', 'matching', 6, '{"pairs": [{"left": "to weather the storm", "right": "enfrentar a tempestade"}, {"left": "to be at a crossroads", "right": "estar numa encruzilhada"}, {"left": "to hit home", "right": "atingir em cheio"}, {"left": "to shed light on", "right": "esclarecer, lançar luz sobre"}, {"left": "to draw the line", "right": "estabelecer um limite"}, {"left": "to bridge the gap", "right": "reduzir a distância"}]}'),
('20000000-0000-0000-0000-000000000367', 'fill_blank', 7, '{"sentence": "The investigation ___ the causes of the failure.", "options": ["shed light on", "hit home", "drew the line"], "correct": "shed light on", "translation": "A investigação esclareceu as causas da falha."}'),
('20000000-0000-0000-0000-000000000367', 'fill_blank', 8, '{"sentence": "The new program aims to ___ between theory and practice.", "options": ["bridge the gap", "weather the storm", "hit home"], "correct": "bridge the gap", "translation": "O novo programa visa reduzir a distância entre teoria e prática."}'),
('20000000-0000-0000-0000-000000000367', 'word_order', 9, '{"words": ["Her", "comment", "about", "the", "delays", "really", "hit", "home"], "correct_sentence": "Her comment about the delays really hit home", "translation": "O comentário dela sobre os atrasos atingiu em cheio"}'),
('20000000-0000-0000-0000-000000000367', 'word_order', 10, '{"words": ["We", "need", "to", "draw", "the", "line", "between", "feedback", "and", "criticism"], "correct_sentence": "We need to draw the line between feedback and criticism", "translation": "Precisamos estabelecer um limite entre feedback e crítica"}'),
('20000000-0000-0000-0000-000000000367', 'reading', 11, '{"passage": "Idioms about challenge and change describe how people face difficulty and uncertainty. A company that ''weathers the storm'' survives a hard period, while someone ''at a crossroads'' must make an important decision. A comment that ''hits home'' feels personally true, and initiatives that ''shed light on'' a problem or ''bridge the gap'' between two groups help create understanding.", "translation": "Idioms sobre desafio e mudança descrevem como as pessoas enfrentam dificuldade e incerteza. Uma empresa que ''weathers the storm'' sobrevive a um período difícil, enquanto alguém ''at a crossroads'' precisa tomar uma decisão importante. Um comentário que ''hits home'' parece pessoalmente verdadeiro, e iniciativas que ''shed light on'' um problema ou ''bridge the gap'' entre dois grupos ajudam a criar compreensão.", "question": "What does a company that ''weathers the storm'' do, according to the text?", "options": ["Survives a hard period", "Causes a crisis", "Ignores a problem"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000367', 'listening', 12, '{"audio_text": "The company managed to weather the storm during the crisis. The organization is at a crossroads and must choose a new direction. The new program aims to bridge the gap between theory and practice.", "question": "What must the organization choose, according to the audio?", "options": ["A new direction", "A new budget", "A new office"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000367', 'dictation', 13, '{"audio_text": "The company managed to weather the storm during the crisis.", "expected": "The company managed to weather the storm during the crisis."}'),
('20000000-0000-0000-0000-000000000367', 'typing', 14, '{"prompt_pt": "Traduza: ''A empresa está numa encruzilhada, mas conseguiu enfrentar a tempestade e agora quer reduzir a distância entre os departamentos.''", "expected": "The company is at a crossroads, but it managed to weather the storm and now wants to bridge the gap between departments.", "ai_review": true}'),

-- Lição 368: Idioms de equilíbrio e conflito (an uphill battle, to set the tone, to strike a balance, to turn a blind eye, to be in the same boat, to move the goalposts)
('20000000-0000-0000-0000-000000000368', 'flashcard', 1, '{"vocabulary_id": "30000000-0000-0000-0000-000000002203", "show_image": false}'),
('20000000-0000-0000-0000-000000000368', 'flashcard', 2, '{"vocabulary_id": "30000000-0000-0000-0000-000000002205", "show_image": false}'),
('20000000-0000-0000-0000-000000000368', 'flashcard', 3, '{"vocabulary_id": "30000000-0000-0000-0000-000000002207", "show_image": false}'),
('20000000-0000-0000-0000-000000000368', 'multiple_choice', 4, '{"question": "Convincing investors was ___.", "audio_text": null, "options": ["an uphill battle", "a grey area", "food for thought"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000368', 'multiple_choice', 5, '{"question": "Management chose to ___ to the problem.", "audio_text": null, "options": ["turn a blind eye", "strike a balance", "set the tone"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000368', 'matching', 6, '{"pairs": [{"left": "an uphill battle", "right": "uma batalha difícil"}, {"left": "to set the tone", "right": "dar o tom"}, {"left": "to strike a balance", "right": "encontrar um equilíbrio"}, {"left": "to turn a blind eye", "right": "fazer vista grossa"}, {"left": "to be in the same boat", "right": "estar no mesmo barco"}, {"left": "to move the goalposts", "right": "mudar as regras no meio do jogo"}]}'),
('20000000-0000-0000-0000-000000000368', 'fill_blank', 7, '{"sentence": "It is hard to ___ between speed and quality.", "options": ["strike a balance", "turn a blind eye", "move the goalposts"], "correct": "strike a balance", "translation": "É difícil encontrar um equilíbrio entre velocidade e qualidade."}'),
('20000000-0000-0000-0000-000000000368', 'fill_blank', 8, '{"sentence": "Every department is ___ when it comes to budget cuts.", "options": ["in the same boat", "an uphill battle", "moving the goalposts"], "correct": "in the same boat", "translation": "Todo departamento está no mesmo barco quando se trata de cortes no orçamento."}'),
('20000000-0000-0000-0000-000000000368', 'word_order', 9, '{"words": ["The", "opening", "speech", "set", "the", "tone", "for", "the", "entire", "conference"], "correct_sentence": "The opening speech set the tone for the entire conference", "translation": "O discurso de abertura deu o tom para toda a conferência"}'),
('20000000-0000-0000-0000-000000000368', 'word_order', 10, '{"words": ["It", "felt", "unfair", "when", "the", "client", "moved", "the", "goalposts", "halfway", "through", "the", "project"], "correct_sentence": "It felt unfair when the client moved the goalposts halfway through the project", "translation": "Pareceu injusto quando o cliente mudou as regras no meio do projeto"}'),
('20000000-0000-0000-0000-000000000368', 'reading', 11, '{"passage": "Idioms about balance and conflict describe how people manage difficult situations together. Something described as ''an uphill battle'' is very hard to achieve, while an opening speech that ''sets the tone'' shapes everything that follows. Teams try to ''strike a balance'' between competing priorities, and everyone feels frustrated when someone ''turns a blind eye'' to a problem or unfairly ''moves the goalposts''.", "translation": "Idioms sobre equilíbrio e conflito descrevem como as pessoas lidam com situações difíceis juntas. Algo descrito como ''an uphill battle'' é muito difícil de alcançar, enquanto um discurso de abertura que ''sets the tone'' molda tudo que vem depois. Equipes tentam ''strike a balance'' entre prioridades concorrentes, e todo mundo fica frustrado quando alguém ''turns a blind eye'' para um problema ou injustamente ''moves the goalposts''.", "question": "What does an opening speech that ''sets the tone'' do, according to the text?", "options": ["Shapes everything that follows", "Ends the event early", "Has no effect"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000368', 'listening', 12, '{"audio_text": "Convincing investors was an uphill battle. It is hard to strike a balance between speed and quality. Every department is in the same boat when it comes to budget cuts.", "question": "What is hard to strike a balance between, according to the audio?", "options": ["Speed and quality", "Investors and clients", "Budget and staff"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000368', 'dictation', 13, '{"audio_text": "Convincing investors was an uphill battle.", "expected": "Convincing investors was an uphill battle."}'),
('20000000-0000-0000-0000-000000000368', 'typing', 14, '{"prompt_pt": "Traduza: ''Foi uma batalha difícil, mas conseguimos encontrar um equilíbrio sem que ninguém mudasse as regras no meio do jogo.''", "expected": "It was an uphill battle, but we managed to strike a balance without anyone moving the goalposts.", "ai_review": true}'),

-- Lição 369: Idioms de risco e percepção (to scratch the surface, a ripple effect, to open a can of worms, to read the room, to rock the boat, to keep something at bay)
