('20000000-0000-0000-0000-000000000369', 'multiple_choice', 5, '{"question": "Asking about the budget ___ in the meeting.", "audio_text": null, "options": ["opened a can of worms", "kept fraud at bay", "read the room"], "correct_index": 0}'),
