('20000000-0000-0000-0000-000000000369', 'fill_blank', 7, '{"sentence": "The price increase had ___ across the whole industry.", "options": ["a ripple effect", "a grey area", "an uphill battle"], "correct": "a ripple effect", "translation": "O aumento de preço teve um efeito cascata em toda a indústria."}'),
('20000000-0000-0000-0000-000000000369', 'fill_blank', 8, '{"sentence": "Regular audits help ___ fraud.", "options": ["keep at bay", "scratch the surface of", "rock the boat with"], "correct": "keep at bay", "translation": "Auditorias regulares ajudam a manter a fraude sob controle."}'),
