('20000000-0000-0000-0000-000000000370', 'matching', 6, '{"pairs": [{"left": "to take something with a grain of salt", "right": "levar algo com ressalvas"}, {"left": "to be a game changer", "right": "ser um divisor de águas"}, {"left": "to leave no stone unturned", "right": "revirar tudo, não deixar pedra sobre pedra"}, {"left": "to go the extra mile", "right": "fazer um esforço extra"}, {"left": "to be the elephant in the room", "right": "ser o elefante na sala"}, {"left": "to come full circle", "right": "fechar o ciclo"}]}'),
('20000000-0000-0000-0000-000000000370', 'fill_blank', 7, '{"sentence": "The budget cuts were ___ during the meeting.", "options": ["the elephant in the room", "a game changer", "a grain of salt"], "correct": "the elephant in the room", "translation": "Os cortes no orçamento eram o elefante na sala durante a reunião."}'),
('20000000-0000-0000-0000-000000000370', 'fill_blank', 8, '{"sentence": "She always ___ for her clients.", "options": ["goes the extra mile", "leaves no stone unturned", "comes full circle"], "correct": "goes the extra mile", "translation": "Ela sempre faz um esforço extra pelos clientes dela."}'),
('20000000-0000-0000-0000-000000000370', 'word_order', 9, '{"words": ["The", "new", "technology", "was", "a", "game", "changer", "for", "the", "industry"], "correct_sentence": "The new technology was a game changer for the industry", "translation": "A nova tecnologia foi um divisor de águas para a indústria"}'),
('20000000-0000-0000-0000-000000000370', 'word_order', 10, '{"words": ["After", "years", "abroad", "her", "career", "came", "full", "circle", "when", "she", "returned", "to", "her", "first", "company"], "correct_sentence": "After years abroad her career came full circle when she returned to her first company", "translation": "Depois de anos no exterior, a carreira dela fechou o ciclo quando voltou para a primeira empresa"}'),
('20000000-0000-0000-0000-000000000370', 'reading', 11, '{"passage": "This final review connects idioms of effort and result to the whole module. A new solution can ''be a game changer'', and a team that ''leaves no stone unturned'' or ''goes the extra mile'' works with real dedication. Meanwhile, a difficult topic that everyone avoids is ''the elephant in the room'', and a story that ends where it began has ''come full circle''. Together with the idioms about clarity, challenge, balance and risk, this vocabulary allows for truly nuanced, C1-level speech.", "translation": "Esta revisão final conecta idioms de esforço e resultado a todo o módulo. Uma nova solução pode ''be a game changer'', e uma equipe que ''leaves no stone unturned'' ou ''goes the extra mile'' trabalha com dedicação de verdade. Enquanto isso, um tema difícil que todo mundo evita é ''the elephant in the room'', e uma história que termina onde começou ''came full circle''. Junto com os idioms de clareza, desafio, equilíbrio e risco, esse vocabulário permite uma fala verdadeiramente matizada, de nível C1.", "question": "According to the text, what is a difficult topic that everyone avoids called?", "options": ["The elephant in the room", "A game changer", "A grain of salt"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000370', 'listening', 12, '{"audio_text": "The new technology was a game changer for the industry. The team left no stone unturned in their search for a solution. The budget cuts were the elephant in the room during the meeting.", "question": "What did the team leave unturned, according to the audio?", "options": ["No stone", "The budget", "The elephant"], "correct_index": 0}'),
('20000000-0000-0000-0000-000000000370', 'dictation', 13, '{"audio_text": "The new technology was a game changer for the industry.", "expected": "The new technology was a game changer for the industry."}'),
('20000000-0000-0000-0000-000000000370', 'typing', 14, '{"prompt_pt": "Traduza: ''Ninguém queria mencionar o elefante na sala, mas a nova tecnologia foi mesmo um divisor de águas.''", "expected": "Nobody wanted to mention the elephant in the room, but the new technology really was a game changer.", "ai_review": true}'),
('20000000-0000-0000-0000-000000000370', 'typing', 15, '{"prompt_pt": "Traduza: ''Depois de revirar tudo e fazer um esforço extra, a carreira dela finalmente fechou o ciclo.''", "expected": "After leaving no stone unturned and going the extra mile, her career finally came full circle.", "ai_review": true}');

